head.script:
    requires("uiplugin.popup");
	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

	scwin.trigger1_onclick = function(e) {

		var options = {
			type : "wframePopup",
			id : "testpopup",
			width : "800px",
			height : "500px", 
			modal : true,
			useHeadingTagTitle : true
		};

		$p.openPopup("wframePopup_layerpopup_WESD-1289_(WSQ-5269)_popup.xml" , options);
	};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('testpopup_header').getElementsByTagName('h2').length == 1;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
